target.css:
:root {
  --ink: #24312b;
  --muted: #68736d;
  --paper: #fffdf7;
  --line: #d9ded2;
  --leaf: #3d7658;
  --leaf-pale: #e3f0e6;
  --clay: #c96843;
}

* {
  box-sizing: border-box;
}

.repair-card {
  width: 480px;
  padding: 18px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--leaf);
  border-radius: 14px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.15;
}

.tag {
  padding: 5px 8px;
  color: var(--leaf);
  background: var(--leaf-pale);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 16px 0;
  padding: 0;
  list-style: none;
}

.detail {
  min-width: 0;
  padding: 10px;
  background: var(--leaf-pale);
  border-radius: 8px;
}

.detail span,
.progress-head span {
  display: block;
  color: var(--muted);
  font-size: 11px;
}

.detail strong {
  display: block;
  margin-top: 4px;
  font-size: 13px;
  line-height: 1.25;
}

.progress {
  padding-top: 2px;
}

.progress-head {
  display: flex;
  justify-content: space-between;
  margin-bottom: 7px;
  font-size: 12px;
}

.track {
  display: block;
  height: 7px;
  overflow: hidden;
  background: var(--line);
  border-radius: 999px;
}

.fill {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--leaf);
  border-radius: inherit;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 16px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  font-size: 13px;
}

.card-footer strong {
  color: var(--clay);
}

button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--ink);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

